//! Study synchronization between the desktop and the server.
//!
//! The contract is an append-only operation journal. Each operation has a stable `op_id`
//! generated by whoever produced it, a `device_id` and a client timestamp. The server
//! applies the operation and writes the row in the same transaction: resending the same
//! `op_id` answers as a duplicate and does not repeat the effect. `seq` is the monotonic
//! cursor of the incremental read — rows are never deleted, so a lower cursor always finds
//! what came after.
//!
//! # Owners
//!
//! The owner is always derived from the caller (HTTP session or the fixed desktop local
//! owner) and never comes from the operation. Read, write and queue filter by owner: no
//! operation crosses users.
//!
//! # Conflict rules
//!
//! - progress: last write wins by `client_at`, with the position clamped to
//!   `[0, MAX_SYNC_POSITION_SECONDS]`; an old write never undoes an already observed
//!   completion, but the newest write can unmark it;
//! - notes: every synced version has a stable identity (`op_id`). The most recent version
//!   (highest `op_id`, since UUID v7 orders by creation instant) takes the main row; the
//!   others become copies with the deterministic id `note_id~op_version`. So two devices
//!   that saw the same set of versions converge to the same texts, without deleting
//!   content;
//! - deletions: a note or bookmark delete records a tombstone with the delete instant. A
//!   create whose own instant is not newer than the tombstone is skipped, so an offline
//!   create never resurrects a deleted row;
//! - card reviews: append-only, applied in cursor order;
//! - preferences: last write wins by `client_at`.
//!
//! Media is not synced. An operation whose media does not exist yet in the local database
//! stays in the journal and is ignored when applied: the data is not lost and convergence
//! happens when the media shows up.
//!
//! # Known limits
//!
//! - `client_at` comes from the device clock; a clock far ahead wins the following writes
//!   until the real clock catches up.
//! - notes written before migration 17 have a null `sync_version`; they are never replaced
//!   by a synced version (that version becomes a copy), so local work older than the
//!   contract is not deleted.

use rusqlite::{Connection, OptionalExtension, params};
use serde::{Deserialize, Serialize};

use crate::db::{Database, now_unix_seconds};
use crate::error::{Error, Result};
use crate::player::{
    MAX_PLAYBACK_SPEED_PERCENT, MIN_PLAYBACK_SPEED_PERCENT, PlayerPreference, valid_language,
};
use crate::study::{
    Flashcard, MediaBookmark, ReviewRating, StudyNote, StudyProgress, validate_owner,
};

/// Largest batch accepted by [`push_operations`].
pub const MAX_SYNC_BATCH: usize = 200;

/// Largest page returned by [`pull_operations`].
pub const MAX_PULL_BATCH: usize = 500;

/// Largest identifier accepted in `op_id` and `device_id`.
pub const MAX_SYNC_ID_CHARS: usize = 128;

/// Ceiling of the synced progress position, in seconds (24 hours).
///
/// The domain does not know the real media duration, so the limit is a coarse ceiling
/// against corrupted values, not the lesson duration.
pub const MAX_SYNC_POSITION_SECONDS: i64 = 24 * 60 * 60;

/// Tombstone kind of a deleted note in `sync_tombstone`.
pub(crate) const TOMBSTONE_NOTE: &str = "note";

/// Tombstone kind of a deleted bookmark in `sync_tombstone`.
pub(crate) const TOMBSTONE_BOOKMARK: &str = "bookmark";

/// Study operation exchanged between devices.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum SyncPayload {
    /// Resume position and completion of a media item.
    Progress {
        /// Opaque media identifier.
        media_id: String,
        /// Resume point in seconds.
        position_seconds: i64,
        /// Lesson completion flag.
        completed: bool,
    },
    /// Note created or edited on the device.
    Note {
        /// Opaque note identifier.
        note_id: String,
        /// Opaque media identifier.
        media_id: String,
        /// Player position in seconds.
        position_seconds: i64,
        /// Note text.
        content: String,
        /// Creation instant reported by the device.
        created_at: i64,
        /// Last edit instant reported by the device.
        updated_at: i64,
    },
    /// Time bookmark created on the device.
    Bookmark {
        /// Opaque bookmark identifier.
        bookmark_id: String,
        /// Opaque media identifier.
        media_id: String,
        /// Media instant in seconds.
        position_seconds: i64,
        /// Short bookmark label.
        label: String,
        /// Creation instant reported by the device.
        created_at: i64,
    },
    /// Note deleted on the device.
    NoteDeleted {
        /// Opaque note identifier.
        note_id: String,
    },
    /// Time bookmark deleted on the device.
    BookmarkDeleted {
        /// Opaque bookmark identifier.
        bookmark_id: String,
    },
    /// Card review, append-only.
    FlashcardReview {
        /// Opaque card identifier.
        card_id: String,
        /// Rating: `again` or `good`.
        rating: String,
        /// Review instant reported by the device.
        reviewed_at: i64,
    },
    /// Playback preferences of the owner.
    Preference {
        /// Video speed as a percentage of normal.
        video_speed: i64,
        /// Audio speed as a percentage of normal.
        audio_speed: i64,
        /// Last subtitle language chosen; empty means no preference.
        subtitle_language: String,
    },
}

impl SyncPayload {
    /// Media referenced by the operation, when there is one.
    pub fn media_id(&self) -> Option<&str> {
        match self {
            Self::Progress { media_id, .. }
            | Self::Note { media_id, .. }
            | Self::Bookmark { media_id, .. } => Some(media_id),
            Self::NoteDeleted { .. }
            | Self::BookmarkDeleted { .. }
            | Self::FlashcardReview { .. }
            | Self::Preference { .. } => None,
        }
    }
}

/// Operation sent by a device.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SyncOperationInput {
    /// Stable operation identifier; resending the same value is idempotent.
    pub op_id: String,
    /// Device instant in Unix seconds.
    pub client_at: i64,
    /// Effect of the operation.
    pub payload: SyncPayload,
}

/// Operation already recorded in the journal.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SyncOperation {
    /// Monotonic cursor assigned by the server.
    pub seq: i64,
    /// Stable operation identifier.
    pub op_id: String,
    /// Device that produced the operation.
    pub device_id: String,
    /// Device instant in Unix seconds.
    pub client_at: i64,
    /// Effect of the operation.
    pub payload: SyncPayload,
}

/// Result of a push.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct PushOutcome {
    /// Operations applied in this call.
    pub applied: usize,
    /// Operations already known by `op_id` (replay).
    pub duplicated: usize,
    /// Highest cursor of the owner after the push.
    pub cursor: i64,
}

/// Page of operations ready for local application.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SyncBatch {
    /// Cursor to use in the next read.
    pub cursor: i64,
    /// Indicates there are still operations after the returned cursor.
    pub has_more: bool,
    /// Operations in ascending `seq` order.
    pub items: Vec<SyncOperation>,
}

/// Local sync state of an owner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncState {
    /// Stable identity of this device.
    pub device_id: String,
    /// Last server cursor already applied locally.
    pub pull_cursor: i64,
}

/// Applies a batch sent by a device and records each operation in the journal.
///
/// The whole batch runs in one transaction: either every new operation enters with its
/// effect, or none enters. An operation with an already known `op_id` counts as a
/// duplicate and is not applied again. Applying normalizes out-of-range data instead of
/// rejecting the batch, so a device never retries forever an operation that can never be
/// accepted.
pub fn push_operations(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    operations: &[SyncOperationInput],
) -> Result<PushOutcome> {
    validate_owner(owner_id)?;
    validate_id(device_id, "device")?;
    if operations.len() > MAX_SYNC_BATCH {
        return Err(Error::InvalidSyncOperation {
            reason: "batch above the limit",
        });
    }

    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let mut applied = 0_usize;
    let mut duplicated = 0_usize;
    for operation in operations {
        validate_id(&operation.op_id, "op")?;
        // `sync_operation.op_id` is a global primary key, so a colliding id from another owner
        // must be refused instead of silently swallowing this operation as a duplicate.
        let existing_owner: Option<String> = transaction
            .query_row(
                "SELECT owner_id FROM sync_operation WHERE op_id = ?1",
                [&operation.op_id],
                |row| row.get(0),
            )
            .optional()?;
        match existing_owner.as_deref() {
            Some(owner) if owner == owner_id => {
                duplicated += 1;
                continue;
            }
            Some(_) => {
                return Err(Error::InvalidSyncOperation {
                    reason: "op_id already used by another owner",
                });
            }
            None => {}
        }
        apply_payload(
            &transaction,
            owner_id,
            &operation.payload,
            operation.client_at,
            &operation.op_id,
        )?;
        transaction.execute(
            "INSERT INTO sync_operation (op_id, owner_id, device_id, client_at, received_at, payload)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![
                operation.op_id,
                owner_id,
                device_id,
                operation.client_at.max(0),
                now_unix_seconds(),
                encode(&operation.payload)?,
            ],
        )?;
        applied += 1;
    }
    let cursor: i64 = transaction.query_row(
        "SELECT COALESCE(MAX(seq), 0) FROM sync_operation WHERE owner_id = ?1",
        [owner_id],
        |row| row.get(0),
    )?;
    transaction.commit()?;

    Ok(PushOutcome {
        applied,
        duplicated,
        cursor,
    })
}

/// Reads the owner's operations after `cursor`, except those of the device itself.
///
/// The device has already applied locally everything it queued; returning its own
/// operations would apply the same write twice. Operations are returned in ascending `seq`
/// order, and the returned cursor is the last item of the page.
pub fn pull_operations(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    cursor: i64,
    limit: usize,
) -> Result<SyncBatch> {
    validate_owner(owner_id)?;
    validate_id(device_id, "device")?;
    let limit = limit.clamp(1, MAX_PULL_BATCH) as i64;

    let conn = db.connection();
    let mut statement = conn.prepare(
        "SELECT seq, op_id, device_id, client_at, payload
           FROM sync_operation
          WHERE owner_id = ?1 AND seq > ?2 AND device_id <> ?3
          ORDER BY seq ASC
          LIMIT ?4",
    )?;
    let rows = statement.query_map(params![owner_id, cursor.max(0), device_id, limit], |row| {
        Ok((
            row.get::<_, i64>(0)?,
            row.get::<_, String>(1)?,
            row.get::<_, String>(2)?,
            row.get::<_, i64>(3)?,
            row.get::<_, String>(4)?,
        ))
    })?;

    let mut items = Vec::new();
    for row in rows {
        let (seq, op_id, device_id, client_at, payload) = row?;
        items.push(SyncOperation {
            seq,
            op_id,
            device_id,
            client_at,
            payload: decode(&payload)?,
        });
    }
    let next_cursor = items.last().map_or(cursor.max(0), |item| item.seq);
    let has_more = conn
        .query_row(
            "SELECT 1 FROM sync_operation
              WHERE owner_id = ?1 AND seq > ?2 AND device_id <> ?3
              LIMIT 1",
            params![owner_id, next_cursor, device_id],
            |_| Ok(()),
        )
        .optional()?
        .is_some();

    Ok(SyncBatch {
        cursor: next_cursor,
        has_more,
        items,
    })
}

/// Applies the received operations locally and stores the cursor, in one transaction.
///
/// The cursor and the effects enter together: a sync interrupted before the commit does
/// not advance the cursor and can resume from the previous point without duplicating
/// operations. `cursor` must be the highest applied `seq`; a value lower than the stored
/// one never moves the cursor back.
pub fn apply_operations(
    db: &Database,
    owner_id: &str,
    operations: &[SyncOperation],
    cursor: i64,
) -> Result<usize> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let mut applied = 0_usize;
    for operation in operations {
        apply_payload(
            &transaction,
            owner_id,
            &operation.payload,
            operation.client_at,
            &operation.op_id,
        )?;
        applied += 1;
    }
    transaction.execute(
        "INSERT INTO sync_state (owner_id, device_id, pull_cursor, updated_at)
         VALUES (?1, ?4, MAX(?2, 0), ?3)
         ON CONFLICT (owner_id) DO UPDATE SET
             pull_cursor = MAX(sync_state.pull_cursor, MAX(excluded.pull_cursor, 0)),
             updated_at = excluded.updated_at",
        params![
            owner_id,
            cursor,
            now_unix_seconds(),
            crate::ids::new_sync_id()
        ],
    )?;
    transaction.commit()?;
    Ok(applied)
}

/// Reads the owner's local state, creating the device identity on the first call.
pub fn sync_state(db: &Database, owner_id: &str) -> Result<SyncState> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    conn.execute(
        "INSERT INTO sync_state (owner_id, device_id, pull_cursor, updated_at)
         VALUES (?1, ?2, 0, ?3)
         ON CONFLICT (owner_id) DO NOTHING",
        params![owner_id, crate::ids::new_sync_id(), now_unix_seconds()],
    )?;
    conn.query_row(
        "SELECT device_id, pull_cursor FROM sync_state WHERE owner_id = ?1",
        [owner_id],
        |row| {
            Ok(SyncState {
                device_id: row.get(0)?,
                pull_cursor: row.get(1)?,
            })
        },
    )
    .map_err(Error::from)
}

/// Queues an operation in the local outbox and returns the `op_id` used.
///
/// The operation is applied locally by the caller (the study write already happened); the
/// outbox only holds what still needs to reach the server. Resending the operation with
/// the same `op_id` is safe: the server recognizes it as a duplicate.
pub fn enqueue_operation(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    payload: &SyncPayload,
    client_at: i64,
) -> Result<String> {
    validate_owner(owner_id)?;
    enqueue_in(db.connection(), owner_id, device_id, payload, client_at)
}

fn enqueue_in(
    conn: &Connection,
    owner_id: &str,
    device_id: &str,
    payload: &SyncPayload,
    client_at: i64,
) -> Result<String> {
    validate_id(device_id, "device")?;
    let op_id = crate::ids::new_sync_id();
    conn.execute(
        "INSERT INTO sync_outbox (op_id, owner_id, device_id, client_at, payload, queued_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            op_id,
            owner_id,
            device_id,
            client_at.max(0),
            encode(payload)?,
            now_unix_seconds(),
        ],
    )?;
    Ok(op_id)
}

/// Records the resume position and queues the same change in a single transaction.
///
/// The transaction is the durability guarantee of the queue: if the outbox insert fails,
/// the study write is not confirmed either, and a crash never leaves the local write
/// without its corresponding operation.
pub fn queue_position(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    media_id: &str,
    position_seconds: i64,
) -> Result<StudyProgress> {
    queue_change(db, owner_id, device_id, |conn| {
        let progress =
            crate::study::record_position_on(conn, owner_id, media_id, position_seconds)?;
        let payload = SyncPayload::Progress {
            media_id: media_id.to_owned(),
            position_seconds,
            completed: progress.completed,
        };
        Ok((progress, payload, now_unix_seconds()))
    })
}

/// Marks completion and queues the same change in a single transaction.
pub fn queue_completed(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    media_id: &str,
    completed: bool,
) -> Result<StudyProgress> {
    queue_change(db, owner_id, device_id, |conn| {
        let progress = crate::study::set_completed_on(conn, owner_id, media_id, completed)?;
        let payload = SyncPayload::Progress {
            media_id: media_id.to_owned(),
            position_seconds: progress.position_seconds,
            completed,
        };
        Ok((progress, payload, now_unix_seconds()))
    })
}

/// Creates a note, marks the local version and queues the operation in one transaction.
pub fn queue_note_create(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    media_id: &str,
    position_seconds: i64,
    content: &str,
) -> Result<StudyNote> {
    queue_note(db, owner_id, device_id, |conn| {
        crate::study::create_study_note_on(conn, owner_id, media_id, position_seconds, content)
    })
}

/// Edits a note, marks the local version and queues the operation in one transaction.
pub fn queue_note_update(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    note_id: &str,
    content: &str,
) -> Result<StudyNote> {
    queue_note(db, owner_id, device_id, |conn| {
        crate::study::update_study_note_on(conn, owner_id, note_id, content)
    })
}

fn queue_note(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    work: impl FnOnce(&Connection) -> Result<StudyNote>,
) -> Result<StudyNote> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let note = work(&transaction)?;
    let payload = SyncPayload::Note {
        note_id: note.note_id.clone(),
        media_id: note.media_id.clone(),
        position_seconds: note.position_seconds,
        content: note.content.clone(),
        created_at: note.created_at,
        updated_at: note.updated_at,
    };
    let op_id = enqueue_in(&transaction, owner_id, device_id, &payload, note.updated_at)?;
    transaction.execute(
        "UPDATE study_note SET sync_version = ?1
          WHERE owner_id = ?2 AND note_id = ?3",
        params![op_id, owner_id, note.note_id],
    )?;
    transaction.commit()?;
    Ok(note)
}

/// Deletes a note and queues the deletion in the same transaction.
///
/// Returns `Ok(false)` when the note did not exist: there is nothing to synchronize and no
/// tombstone is needed.
pub fn queue_note_delete(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    note_id: &str,
) -> Result<bool> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let Some(deleted_at) = crate::study::delete_study_note_on(&transaction, owner_id, note_id)?
    else {
        return Ok(false);
    };
    let payload = SyncPayload::NoteDeleted {
        note_id: note_id.to_owned(),
    };
    enqueue_in(&transaction, owner_id, device_id, &payload, deleted_at)?;
    transaction.commit()?;
    Ok(true)
}

/// Creates a bookmark and queues the operation in a single transaction.
pub fn queue_bookmark_create(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    media_id: &str,
    position_seconds: i64,
    label: &str,
) -> Result<MediaBookmark> {
    queue_change(db, owner_id, device_id, |conn| {
        let bookmark = crate::study::create_media_bookmark_on(
            conn,
            owner_id,
            media_id,
            position_seconds,
            label,
        )?;
        Ok((
            bookmark.clone(),
            SyncPayload::Bookmark {
                bookmark_id: bookmark.bookmark_id,
                media_id: bookmark.media_id,
                position_seconds: bookmark.position_seconds,
                label: bookmark.label,
                created_at: bookmark.created_at,
            },
            bookmark.created_at,
        ))
    })
}

/// Deletes a bookmark and queues the deletion in the same transaction.
///
/// Returns `Ok(false)` when the bookmark did not exist.
pub fn queue_bookmark_delete(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    bookmark_id: &str,
) -> Result<bool> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let Some(deleted_at) =
        crate::study::delete_media_bookmark_on(&transaction, owner_id, bookmark_id)?
    else {
        return Ok(false);
    };
    let payload = SyncPayload::BookmarkDeleted {
        bookmark_id: bookmark_id.to_owned(),
    };
    enqueue_in(&transaction, owner_id, device_id, &payload, deleted_at)?;
    transaction.commit()?;
    Ok(true)
}

/// Records a card review and queues the operation in a single transaction.
pub fn queue_review(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    card_id: &str,
    rating: ReviewRating,
) -> Result<Flashcard> {
    queue_change(db, owner_id, device_id, |conn| {
        let card = crate::study::review_flashcard_on(conn, owner_id, card_id, rating)?;
        Ok((
            card.clone(),
            SyncPayload::FlashcardReview {
                card_id: card.card_id,
                rating: rating.as_str().to_owned(),
                reviewed_at: card.updated_at,
            },
            card.updated_at,
        ))
    })
}

/// Stores the playback preferences and queues the operation in a single transaction.
pub fn queue_preference(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    video_speed: i64,
    audio_speed: i64,
    subtitle_language: &str,
) -> Result<PlayerPreference> {
    queue_change(db, owner_id, device_id, |conn| {
        let preference = crate::player::set_player_preference_on(
            conn,
            owner_id,
            video_speed,
            audio_speed,
            subtitle_language,
        )?;
        Ok((
            preference.clone(),
            SyncPayload::Preference {
                video_speed: preference.video_speed,
                audio_speed: preference.audio_speed,
                subtitle_language: preference.subtitle_language,
            },
            preference.updated_at,
        ))
    })
}

fn queue_change<T>(
    db: &Database,
    owner_id: &str,
    device_id: &str,
    work: impl FnOnce(&Connection) -> Result<(T, SyncPayload, i64)>,
) -> Result<T> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let (value, payload, client_at) = work(&transaction)?;
    enqueue_in(&transaction, owner_id, device_id, &payload, client_at)?;
    transaction.commit()?;
    Ok(value)
}

/// Lists the pending outbox operations, from the oldest to the newest.
pub fn pending_operations(
    db: &Database,
    owner_id: &str,
    limit: usize,
) -> Result<Vec<SyncOperationInput>> {
    validate_owner(owner_id)?;
    let limit = limit.clamp(1, MAX_SYNC_BATCH) as i64;
    let conn = db.connection();
    let mut statement = conn.prepare(
        "SELECT op_id, client_at, payload FROM sync_outbox
          WHERE owner_id = ?1
          ORDER BY queued_at ASC, op_id ASC
          LIMIT ?2",
    )?;
    let rows = statement.query_map(params![owner_id, limit], |row| {
        Ok((
            row.get::<_, String>(0)?,
            row.get::<_, i64>(1)?,
            row.get::<_, String>(2)?,
        ))
    })?;
    let mut operations = Vec::new();
    for row in rows {
        let (op_id, client_at, payload) = row?;
        operations.push(SyncOperationInput {
            op_id,
            client_at,
            payload: decode(&payload)?,
        });
    }
    Ok(operations)
}

/// Counts the operations still pending in the owner's outbox.
pub fn pending_count(db: &Database, owner_id: &str) -> Result<i64> {
    validate_owner(owner_id)?;
    db.connection()
        .query_row(
            "SELECT COUNT(*) FROM sync_outbox WHERE owner_id = ?1",
            [owner_id],
            |row| row.get(0),
        )
        .map_err(Error::from)
}

/// Removes the outbox operations accepted by the server and returns how many were removed.
pub fn acknowledge_operations(db: &Database, owner_id: &str, op_ids: &[String]) -> Result<usize> {
    validate_owner(owner_id)?;
    let conn = db.connection();
    let transaction = conn.unchecked_transaction()?;
    let mut removed = 0_usize;
    for op_id in op_ids {
        removed += transaction.execute(
            "DELETE FROM sync_outbox WHERE owner_id = ?1 AND op_id = ?2",
            params![owner_id, op_id],
        )?;
    }
    transaction.commit()?;
    Ok(removed)
}

fn apply_payload(
    conn: &Connection,
    owner_id: &str,
    payload: &SyncPayload,
    client_at: i64,
    op_id: &str,
) -> Result<()> {
    match payload {
        SyncPayload::Progress {
            media_id,
            position_seconds,
            completed,
        } => apply_progress(
            conn,
            owner_id,
            media_id,
            *position_seconds,
            *completed,
            client_at,
        ),
        SyncPayload::Note {
            note_id,
            media_id,
            position_seconds,
            content,
            created_at,
            updated_at,
        } => apply_note(
            conn,
            owner_id,
            note_id,
            media_id,
            *position_seconds,
            content,
            *created_at,
            *updated_at,
            op_id,
        ),
        SyncPayload::Bookmark {
            bookmark_id,
            media_id,
            position_seconds,
            label,
            created_at,
        } => apply_bookmark(
            conn,
            owner_id,
            bookmark_id,
            media_id,
            *position_seconds,
            label,
            *created_at,
        ),
        SyncPayload::NoteDeleted { note_id } => {
            apply_note_delete(conn, owner_id, note_id, client_at)
        }
        SyncPayload::BookmarkDeleted { bookmark_id } => {
            apply_bookmark_delete(conn, owner_id, bookmark_id, client_at)
        }
        SyncPayload::FlashcardReview {
            card_id,
            rating,
            reviewed_at,
        } => apply_review(conn, owner_id, card_id, rating, *reviewed_at),
        SyncPayload::Preference {
            video_speed,
            audio_speed,
            subtitle_language,
        } => apply_preference(
            conn,
            owner_id,
            *video_speed,
            *audio_speed,
            subtitle_language,
            client_at,
        ),
    }
}

fn apply_progress(
    conn: &Connection,
    owner_id: &str,
    media_id: &str,
    position_seconds: i64,
    completed: bool,
    client_at: i64,
) -> Result<()> {
    if !media_known(conn, media_id)? {
        return Ok(());
    }
    let position = position_seconds.clamp(0, MAX_SYNC_POSITION_SECONDS);
    let client_at = client_at.max(0);
    let existing: Option<(i64, i64, i64)> = conn
        .query_row(
            "SELECT position_seconds, completed, updated_at FROM study_state
              WHERE owner_id = ?1 AND media_id = ?2",
            params![owner_id, media_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;

    let Some((current_position, current_completed, current_updated_at)) = existing else {
        conn.execute(
            "INSERT INTO study_state (owner_id, media_id, position_seconds, completed, updated_at)
             VALUES (?1, ?2, ?3, ?4, ?5)",
            params![
                owner_id,
                media_id,
                position,
                i64::from(completed),
                client_at
            ],
        )?;
        return Ok(());
    };

    // Position: the newest write wins. Completion: once observed it is never undone —
    // neither by a newer write nor by an older one that arrives late.
    let newer = client_at >= current_updated_at;
    let next_position = if newer { position } else { current_position };
    let next_completed = current_completed != 0 || completed;
    if next_position == current_position && next_completed == (current_completed != 0) {
        return Ok(());
    }
    conn.execute(
        "UPDATE study_state
            SET position_seconds = ?1, completed = ?2, updated_at = ?3
          WHERE owner_id = ?4 AND media_id = ?5",
        params![
            next_position,
            i64::from(next_completed),
            current_updated_at.max(client_at),
            owner_id,
            media_id
        ],
    )?;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn apply_note(
    conn: &Connection,
    owner_id: &str,
    note_id: &str,
    media_id: &str,
    position_seconds: i64,
    content: &str,
    created_at: i64,
    updated_at: i64,
    op_id: &str,
) -> Result<()> {
    let content = content.trim();
    if note_id.trim().is_empty()
        || content.is_empty()
        || content.chars().count() > 10_000
        || position_seconds < 0
        || !media_known(conn, media_id)?
    {
        return Ok(());
    }
    let created_at = created_at.clamp(0, updated_at.max(0));
    let updated_at = updated_at.max(created_at);
    // A delete at or after this version wins: an old create never resurrects a newer delete.
    if tombstone_blocks(conn, owner_id, TOMBSTONE_NOTE, note_id, updated_at)? {
        return Ok(());
    }

    let existing: Option<(String, String, Option<String>, i64, i64, i64)> = conn
        .query_row(
            "SELECT owner_id, content, sync_version, position_seconds, created_at, updated_at
               FROM study_note WHERE note_id = ?1",
            [note_id],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                ))
            },
        )
        .optional()?;

    let Some((row_owner, row_content, row_version, row_position, row_created, row_updated)) =
        existing
    else {
        insert_note(
            conn,
            note_id,
            owner_id,
            media_id,
            position_seconds,
            content,
            created_at,
            updated_at,
            op_id,
        )?;
        return Ok(());
    };

    if row_owner != owner_id {
        // The note identity is opaque and global; an id already used by another owner is
        // never overwritten. The received version becomes a copy of the owner that sent it.
        insert_note(
            conn,
            &copy_id(note_id, op_id),
            owner_id,
            media_id,
            position_seconds,
            content,
            created_at,
            updated_at,
            op_id,
        )?;
        return Ok(());
    }

    if row_content == content {
        return Ok(());
    }

    match row_version {
        // Row from before the contract: local work is never replaced.
        None => insert_note(
            conn,
            &copy_id(note_id, op_id),
            owner_id,
            media_id,
            position_seconds,
            content,
            created_at,
            updated_at,
            op_id,
        ),
        // The received version is newer (UUID v7 orders by time): it takes the main row
        // and the current version is preserved as a copy.
        Some(version) if version.as_str() < op_id => {
            insert_note(
                conn,
                &copy_id(note_id, &version),
                owner_id,
                media_id,
                row_position,
                &row_content,
                row_created,
                row_updated,
                &version,
            )?;
            conn.execute(
                "UPDATE study_note
                    SET position_seconds = ?1, content = ?2, created_at = ?3,
                        updated_at = ?4, sync_version = ?5
                  WHERE note_id = ?6",
                params![
                    position_seconds,
                    content,
                    created_at,
                    updated_at,
                    op_id,
                    note_id
                ],
            )?;
            Ok(())
        }
        // The received version is older and only survives as a copy.
        Some(_) => insert_note(
            conn,
            &copy_id(note_id, op_id),
            owner_id,
            media_id,
            position_seconds,
            content,
            created_at,
            updated_at,
            op_id,
        ),
    }
}

#[allow(clippy::too_many_arguments)]
fn insert_note(
    conn: &Connection,
    note_id: &str,
    owner_id: &str,
    media_id: &str,
    position_seconds: i64,
    content: &str,
    created_at: i64,
    updated_at: i64,
    sync_version: &str,
) -> Result<()> {
    conn.execute(
        "INSERT OR IGNORE INTO study_note
             (note_id, owner_id, media_id, position_seconds, content, created_at, updated_at, sync_version)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
        params![
            note_id,
            owner_id,
            media_id,
            position_seconds,
            content,
            created_at,
            updated_at,
            sync_version
        ],
    )?;
    Ok(())
}

/// Deterministic identity of the copy of a losing note version.
fn copy_id(note_id: &str, version: &str) -> String {
    format!("{note_id}~{version}")
}

fn apply_bookmark(
    conn: &Connection,
    owner_id: &str,
    bookmark_id: &str,
    media_id: &str,
    position_seconds: i64,
    label: &str,
    created_at: i64,
) -> Result<()> {
    let label = label.trim();
    if bookmark_id.trim().is_empty()
        || label.is_empty()
        || label.chars().count() > crate::study::MAX_BOOKMARK_LABEL_CHARS
        || position_seconds < 0
        || !media_known(conn, media_id)?
    {
        return Ok(());
    }
    // A delete at or after this version wins: an old create never resurrects a newer delete.
    if tombstone_blocks(conn, owner_id, TOMBSTONE_BOOKMARK, bookmark_id, created_at)? {
        return Ok(());
    }
    conn.execute(
        "INSERT OR IGNORE INTO media_bookmark
             (bookmark_id, owner_id, media_id, position_seconds, label, created_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            bookmark_id,
            owner_id,
            media_id,
            position_seconds,
            label,
            created_at.max(0)
        ],
    )?;
    Ok(())
}

/// Deletes the owner's note and records the tombstone. An absent note is not an error:
/// the delete converges.
fn apply_note_delete(
    conn: &Connection,
    owner_id: &str,
    note_id: &str,
    deleted_at: i64,
) -> Result<()> {
    let note_id = note_id.trim();
    if note_id.is_empty() {
        return Ok(());
    }
    let deleted_at = deleted_at.max(0);
    conn.execute(
        "DELETE FROM study_note WHERE owner_id = ?1 AND note_id = ?2",
        params![owner_id, note_id],
    )?;
    record_tombstone_on(conn, owner_id, TOMBSTONE_NOTE, note_id, deleted_at)
}

/// Deletes the owner's bookmark and records the tombstone; an absent row is not an error.
fn apply_bookmark_delete(
    conn: &Connection,
    owner_id: &str,
    bookmark_id: &str,
    deleted_at: i64,
) -> Result<()> {
    let bookmark_id = bookmark_id.trim();
    if bookmark_id.is_empty() {
        return Ok(());
    }
    let deleted_at = deleted_at.max(0);
    conn.execute(
        "DELETE FROM media_bookmark WHERE owner_id = ?1 AND bookmark_id = ?2",
        params![owner_id, bookmark_id],
    )?;
    record_tombstone_on(conn, owner_id, TOMBSTONE_BOOKMARK, bookmark_id, deleted_at)
}

/// Records a delete instant, keeping the newest one already stored.
pub(crate) fn record_tombstone_on(
    conn: &Connection,
    owner_id: &str,
    kind: &str,
    target_id: &str,
    deleted_at: i64,
) -> Result<()> {
    conn.execute(
        "INSERT INTO sync_tombstone (owner_id, kind, target_id, deleted_at)
         VALUES (?1, ?2, ?3, ?4)
         ON CONFLICT (owner_id, kind, target_id) DO UPDATE SET
             deleted_at = MAX(sync_tombstone.deleted_at, excluded.deleted_at)",
        params![owner_id, kind, target_id, deleted_at],
    )?;
    Ok(())
}

/// Whether a delete at or after `version_at` already happened for this row.
fn tombstone_blocks(
    conn: &Connection,
    owner_id: &str,
    kind: &str,
    target_id: &str,
    version_at: i64,
) -> Result<bool> {
    Ok(conn
        .query_row(
            "SELECT 1 FROM sync_tombstone
              WHERE owner_id = ?1 AND kind = ?2 AND target_id = ?3 AND deleted_at >= ?4",
            params![owner_id, kind, target_id, version_at.max(0)],
            |_| Ok(()),
        )
        .optional()?
        .is_some())
}

fn apply_review(
    conn: &Connection,
    owner_id: &str,
    card_id: &str,
    rating: &str,
    reviewed_at: i64,
) -> Result<()> {
    let Some(rating) = crate::study::ReviewRating::parse(rating) else {
        return Ok(());
    };
    let reviewed_at = reviewed_at.max(0);
    let previous: Option<i64> = conn
        .query_row(
            "SELECT interval_days FROM flashcard WHERE owner_id = ?1 AND card_id = ?2",
            params![owner_id, card_id],
            |row| row.get(0),
        )
        .optional()?;
    let Some(previous_interval) = previous else {
        // Cards are not synced, so a review of an unknown card cannot be applied anywhere;
        // it stays only in the journal for audit. Tracked in #472.
        return Ok(());
    };
    let (next_interval, next_due) =
        crate::study::schedule_review(previous_interval, rating, reviewed_at);
    conn.execute(
        "UPDATE flashcard
            SET interval_days = ?1, next_due = ?2, updated_at = ?3
          WHERE owner_id = ?4 AND card_id = ?5",
        params![next_interval, next_due, reviewed_at, owner_id, card_id],
    )?;
    conn.execute(
        "INSERT INTO flashcard_review
             (owner_id, card_id, rating, previous_interval_days, next_due, reviewed_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            owner_id,
            card_id,
            rating.as_str(),
            previous_interval,
            next_due,
            reviewed_at
        ],
    )?;
    Ok(())
}

fn apply_preference(
    conn: &Connection,
    owner_id: &str,
    video_speed: i64,
    audio_speed: i64,
    subtitle_language: &str,
    client_at: i64,
) -> Result<()> {
    if !valid_language(subtitle_language) {
        return Ok(());
    }
    let client_at = client_at.max(0);
    let video_speed = video_speed.clamp(MIN_PLAYBACK_SPEED_PERCENT, MAX_PLAYBACK_SPEED_PERCENT);
    let audio_speed = audio_speed.clamp(MIN_PLAYBACK_SPEED_PERCENT, MAX_PLAYBACK_SPEED_PERCENT);
    conn.execute(
        "INSERT INTO player_preference
             (owner_id, video_speed, audio_speed, subtitle_language, updated_at)
         VALUES (?1, ?2, ?3, ?4, ?5)
         ON CONFLICT (owner_id) DO UPDATE SET
             video_speed = excluded.video_speed,
             audio_speed = excluded.audio_speed,
             subtitle_language = excluded.subtitle_language,
             updated_at = excluded.updated_at
         WHERE excluded.updated_at >= player_preference.updated_at",
        params![
            owner_id,
            video_speed,
            audio_speed,
            subtitle_language,
            client_at
        ],
    )?;
    Ok(())
}

fn media_known(conn: &Connection, media_id: &str) -> Result<bool> {
    Ok(conn
        .query_row(
            "SELECT 1 FROM media WHERE media_id = ?1",
            [media_id],
            |_| Ok(()),
        )
        .optional()?
        .is_some())
}

fn validate_id(value: &str, field: &'static str) -> Result<()> {
    if value.trim().is_empty() || value.chars().count() > MAX_SYNC_ID_CHARS {
        return Err(Error::InvalidSyncOperation { reason: field });
    }
    Ok(())
}

fn encode(payload: &SyncPayload) -> Result<String> {
    serde_json::to_string(payload).map_err(|_| Error::InvalidSyncOperation {
        reason: "unreadable payload",
    })
}

fn decode(payload: &str) -> Result<SyncPayload> {
    serde_json::from_str(payload).map_err(|_| Error::InvalidSyncOperation {
        reason: "unreadable payload",
    })
}
